import React, { useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';

const CursoDetalle = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  // Suponiendo que los cursos vienen de una API o base de datos
  const curso = {
    id,
    nombre: id === '1' ? 'Curso de React' : 'Curso de JavaScript',
    descripcion: id === '1' ? 'Aprende a desarrollar aplicaciones web con React.' : 'Domina el lenguaje de programación JavaScript.',
    precio: 100, // Definimos un precio estático por ejemplo
  };

  // Estado para los datos del formulario
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    edad: '',
    ocupacion: '',
  });

  // Manejar cambios en los inputs
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  // Manejar el envío del formulario de inscripción
  const handleSubmit = (e) => {
    e.preventDefault();

    // Lógica para manejar la inscripción
    // Aquí podrías enviar los datos al backend y luego redirigir a la página de pago

    console.log('Datos del formulario:', formData);
    
    // Redirigir a la página de pago con el ID del curso
    navigate(`/pago/${curso.id}`);
  };

  return (
    <div className="curso-detalle">
      <div className="curso-info">
        <h1>{curso.nombre}</h1>
        <p>{curso.descripcion}</p>
        <p><strong>Precio: ${curso.precio}</strong></p>
      </div>

      {/* Formulario de inscripción */}
      <div className="inscripcion-form">
        <h2>Inscribirse al curso</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            name="nombre"
            placeholder="Nombre"
            onChange={handleChange}
            required
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="telefono"
            placeholder="Teléfono"
            onChange={handleChange}
            required
          />
          <input
            type="number"
            name="edad"
            placeholder="Edad"
            onChange={handleChange}
            required
          />
          <input
            type="text"
            name="ocupacion"
            placeholder="Ocupación"
            onChange={handleChange}
            required
          />
          <button type="submit">Inscribirse</button>
        </form>
      </div>
    </div>
  );
};

export default CursoDetalle;
